    top = edge_run(grid[0])
    bottom = edge_run(grid[-1])
    if top and bottom and top[2] == bottom[2] and top[1]-top[0] == bottom[1]-bottom[0]:
        a,b = top[0], top[1]
        # Markers in the upper half of the lane group extend from top; paired
        # column is filled from the same side. Lower edge is symmetric.
        for r in range(1,h-1):
            for c in range(a,b):
                x=grid[r][c]
                if x != bg:
                    for rr in range(1,r):
                        if grid[rr][c] == bg: out[rr][c]=x
                    out[r][c]=4
                    d=bottom[0]+c-a
                    for rr in range(1,r):
                        if grid[rr][d] == bg: out[rr][d]=x
            for c in range(bottom[0],bottom[1]):
                x=grid[r][c]
                if x != bg:
                    for rr in range(r+1,h-1):
                        if grid[rr][c] == bg: out[rr][c]=x
                    out[r][c]=4
                    d=top[0]+c-bottom[0]
                    for rr in range(r+1,h-1):
                        if grid[rr][d] == bg: out[rr][d]=x
        return out

