    # side toward the center, and project onto the corresponding opposite row.
    left=edge_run([grid[r][0] for r in range(h)])
    right=edge_run([grid[r][-1] for r in range(h)])
    if left and right and left[2]==right[2] and left[1]-left[0]==right[1]-right[0]:
        for r in range(left[0],left[1]):
            for c in range(1,w-1):
                x=grid[r][c]
                if x != bg:
                    for cc in range(1,c):
                        if grid[r][cc] == bg: out[r][cc]=x
                    out[r][c]=4
                    rr=right[0]+r-left[0]
                    for cc in range(1,c):
                        if grid[rr][cc] == bg: out[rr][cc]=x
        for r in range(right[0],right[1]):
            for c in range(1,w-1):
                x=grid[r][c]
                if x != bg:
                    for cc in range(c+1,w-1):
                        if grid[r][cc] == bg: out[r][cc]=x
                    out[r][c]=4
                    rr=left[0]+r-right[0]
                    for cc in range(c+1,w-1):
